insertChunk(row: { path: string; text: string; meta?: string | null; vector: number[] }): void {
  this.db.exec({
    sql: "INSERT INTO chunks(path, text, meta, vector) VALUES(?, ?, ?, vector_as_f32(?))",
    bind: [
      row.path,
      row.text,
      row.meta ?? null,
      JSON.stringify(row.vector),
    ],
  });
}

