update_md5_1c44d411b668c501f011fb50ad553.find_text:
quantize(preload: boolean = false): void {
  this.db.exec({
    sql: "SELECT vector_quantize('chunks', 'vector');",
  });
  if (preload) {
    this.db.exec({
      sql: "SELECT vector_quantize_preload('chunks', 'vector');",
    });
  }
}

